// Rejects the request unless it carries the shared secret Next.js sends.
// Set MENU_PROFIT_WEBHOOK_SECRET in n8n's environment variables (Settings
// > Variables, or the process env of your n8n host) to the SAME value as
// Next.js's N8N_WEBHOOK_SECRET. Never hardcode the secret here.
const expected = $env.MENU_PROFIT_WEBHOOK_SECRET;
const provided = $input.first().json.headers['x-webhook-secret'];

if (!expected) {
  throw new Error('MENU_PROFIT_WEBHOOK_SECRET is not set on this n8n instance.');
}
if (provided !== expected) {
  throw new Error('Invalid or missing x-webhook-secret header.');
}

const body = $input.first().json.body ?? {};
const auditId = body.auditId;
if (!auditId || typeof auditId !== 'string') {
  throw new Error('Request body is missing auditId.');
}

return [{ json: { auditId } }];

// Deterministic parsing for the slots that are already tabular
// (Excel/CSV) — no AI involved here, exactly per the spec's
// "calculate using deterministic code, not AI" requirement for
// anything that doesn't genuinely need it. PDF/image files are
// passed through untouched for the AI-extraction branch instead.
const XLSX = require('xlsx');

const webhookItem = $('Webhook').first();
const binaries = webhookItem.binary || {};
const auditId = $json.auditId;

function isSpreadsheet(mimeType) {
  return (
    mimeType === 'text/csv' ||
    mimeType === 'application/vnd.ms-excel' ||
    mimeType ===
      'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
  );
}

function parseSheet(buffer) {
  const wb = XLSX.read(buffer, { type: 'buffer' });
  const sheet = wb.Sheets[wb.SheetNames[0]];
  return XLSX.utils.sheet_to_json(sheet, { defval: null });
}

const menuRows = [];
const posRows = [];
const invoiceRows = [];
const filesNeedingAi = []; // { slot, fileName, mimeType, base64 }

for (const [key, binary] of Object.entries(binaries)) {
  const slot = key.startsWith('invoices')
    ? 'invoices'
    : key.startsWith('menu')
      ? 'menu'
      : key.startsWith('pos')
        ? 'pos'
        : null;
  if (!slot) continue;

  const buffer = Buffer.from(binary.data, 'base64');

  if (isSpreadsheet(binary.mimeType)) {
    const rows = parseSheet(buffer);
    if (slot === 'menu') menuRows.push(...rows.map((r) => ({ ...r, __source: binary.fileName })));
    if (slot === 'pos') posRows.push(...rows.map((r) => ({ ...r, __source: binary.fileName })));
    if (slot === 'invoices') invoiceRows.push(...rows.map((r) => ({ ...r, __source: binary.fileName })));
  } else {
    // PDF or image — needs the AI-extraction branch.
    filesNeedingAi.push({
      slot,
      fileName: binary.fileName,
      mimeType: binary.mimeType,
      base64: binary.data,
    });
  }
}

return [
  {
    json: {
      auditId,
      menuRows,
      posRows,
      invoiceRows,
      filesNeedingAi,
      needsAiExtraction: filesNeedingAi.length > 0,
    },
  },
];

