// Claude is asked to return ONLY a JSON object; this just parses it
// defensively. A malformed response doesn't crash the workflow — it
// routes the audit to "review_required" instead (see the Merge step),
// per "flag uncertain matches instead of inventing facts".
let aiMenuItems = [];
let aiInvoiceLines = [];
let aiParseError = null;

try {
  const text = $json.content?.[0]?.text ?? '';
  const match = text.match(/\{[\s\S]*\}/);
  const parsed = JSON.parse(match ? match[0] : text);
  aiMenuItems = Array.isArray(parsed.menuItems) ? parsed.menuItems : [];
  aiInvoiceLines = Array.isArray(parsed.invoiceLines) ? parsed.invoiceLines : [];
} catch (error) {
  aiParseError = String(error);
}

return [{ json: { aiMenuItems, aiInvoiceLines, aiParseError } }];

// The "no AI needed" branch — keep the output shape identical to
// "Parse Claude Response" so the next node doesn't need to know which
// branch ran.
return [{ json: { aiMenuItems: [], aiInvoiceLines: [], aiParseError: null } }];

// Combines the deterministically-parsed spreadsheet rows with whatever
// Claude extracted from PDFs/images into one consistent shape. Field
// names here intentionally mirror lib/audit/calculations.ts's inputs —
// keep both in sync by hand (see n8n/README.md "Known limitations").
const parsed = $('Parse Spreadsheet Files').first().json;
const ai = $json; // aiMenuItems / aiInvoiceLines / aiParseError

function toNumber(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/[^0-9.\-]/g, ''));
  return Number.isFinite(n) ? n : null;
}

const menuItems = [
  ...parsed.menuRows.map((r) => ({
    name: r.name ?? r.Item ?? r['Item Name'] ?? null,
    category: r.category ?? r.Category ?? null,
    sellingPrice: toNumber(r.price ?? r.Price ?? r['Selling Price']),
    source: 'spreadsheet',
  })),
  ...ai.aiMenuItems.map((r) => ({
    name: r.name ?? null,
    category: r.category ?? null,
    sellingPrice: toNumber(r.sellingPrice ?? r.price),
    source: 'ai',
  })),
].filter((item) => item.name);

const ingredients = [
  ...parsed.invoiceRows.map((r) => ({
    name: r.ingredient ?? r.Ingredient ?? r['Item'] ?? null,
    quantity: toNumber(r.quantity ?? r.Quantity),
    unit: r.unit ?? r.Unit ?? null,
    packSize: r.packSize ?? r['Pack Size'] ?? null,
    price: toNumber(r.price ?? r.Price),
    source: 'spreadsheet',
  })),
  ...ai.aiInvoiceLines.map((r) => ({
    name: r.ingredientName ?? r.name ?? null,
    quantity: toNumber(r.quantity),
    unit: r.unit ?? null,
    packSize: r.packSize ?? null,
    price: toNumber(r.price),
    source: 'ai',
  })),
].filter((item) => item.name);

const posSales = parsed.posRows.map((r) => ({
  name: r.item ?? r.Item ?? r['Item Name'] ?? null,
  unitsSold: toNumber(r.units ?? r.Units ?? r['Units Sold']),
  revenue: toNumber(r.revenue ?? r.Revenue),
})).filter((item) => item.name);

const reviewRequired = ai.aiParseError
  ? [{ reason: 'AI extraction response could not be parsed', detail: ai.aiParseError }]
  : [];

return [{
  json: {
    auditId: parsed.auditId,
    menuItems,
    ingredients,
    posSales,
    reviewRequired,
  },
}];

// Matches each menu item to its ingredients (by substring/word-overlap
// name matching — good enough for Phase 1, not a real NLP matcher) and
// to its POS sales row. Anything that doesn't match confidently is
// pushed into reviewRequired rather than guessed at.
const { auditId, menuItems, ingredients, posSales, reviewRequired } = $json;

function normalize(s) {
  return String(s ?? '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
}

function findBestMatch(name, candidates) {
  const target = normalize(name);
  let best = null;
  let bestScore = 0;
  for (const c of candidates) {
    const candidateName = normalize(c.name);
    if (!candidateName) continue;
    const score = target === candidateName ? 1 : (target.includes(candidateName) || candidateName.includes(target)) ? 0.7 : 0;
    if (score > bestScore) {
      bestScore = score;
      best = c;
    }
  }
  return bestScore >= 0.7 ? best : null;
}

const review = [...reviewRequired];
const matched = menuItems.map((item) => {
  const posMatch = findBestMatch(item.name, posSales);
  if (!posMatch) {
    review.push({ reason: 'No POS sales match', item: item.name });
  }

  // A menu item can use several ingredients; Phase 1 assumes a 1:1
  // name match per line (e.g. a "Cheeseburger" menu item matching a
  // "Cheeseburger" ingredient costing row) rather than a real recipe/BOM.
  // Real recipe composition is Phase 2 scope — see n8n/README.md.
  const ingredientMatch = findBestMatch(item.name, ingredients);
  if (!ingredientMatch) {
    review.push({ reason: 'No supplier cost match', item: item.name });
  }

  return {
    name: item.name,
    category: item.category,
    sellingPrice: item.sellingPrice,
    unitsSold: posMatch ? posMatch.unitsSold : null,
    ingredientCost: ingredientMatch ? ingredientMatch.price : null,
    ingredientName: ingredientMatch ? ingredientMatch.name : null,
  };
});

return [{ json: { auditId, matchedItems: matched, ingredients, reviewRequired: review } }];

// Same formulas as lib/audit/calculations.ts in the Next.js app —
// deliberately duplicated (different runtime) rather than shared.
// Keep both in sync by hand; see n8n/README.md "Known limitations".
const { auditId, matchedItems, reviewRequired } = $json;

function gp(item) {
  if (item.sellingPrice == null || item.ingredientCost == null) return null;
  return item.sellingPrice - item.ingredientCost;
}
function gpPercent(item, grossProfit) {
  if (item.sellingPrice == null || !item.sellingPrice || grossProfit == null) return null;
  return (grossProfit / item.sellingPrice) * 100;
}

const totalUnits = matchedItems.reduce((sum, i) => sum + (i.unitsSold ?? 0), 0);

const costing = matchedItems.map((item) => {
  const grossProfit = gp(item);
  const gpPct = gpPercent(item, grossProfit);
  const totalGpContribution = grossProfit != null && item.unitsSold != null ? grossProfit * item.unitsSold : null;
  const salesMix = item.unitsSold != null && totalUnits > 0 ? (item.unitsSold / totalUnits) * 100 : null;

  return {
    name: item.name,
    category: item.category,
    sellingPrice: item.sellingPrice,
    ingredientCost: item.ingredientCost,
    grossProfitPerPortion: grossProfit,
    gpPercent: gpPct,
    unitsSold: item.unitsSold,
    totalGpContribution,
    salesMixPercent: salesMix,
    confidence: item.sellingPrice != null && item.ingredientCost != null && item.unitsSold != null ? 'verified' : 'incomplete',
  };
});

const summary = {
  auditId,
  totalItems: matchedItems.length,
  itemsVerified: costing.filter((c) => c.confidence === 'verified').length,
  itemsIncomplete: costing.filter((c) => c.confidence === 'incomplete').length,
  totalUnitsSold: totalUnits,
  totalGpContribution: costing.reduce((sum, c) => sum + (c.totalGpContribution ?? 0), 0),
  reviewItemCount: reviewRequired.length,
  generatedAt: new Date().toISOString(),
};

return [{ json: { auditId, costing, summary, reviewRequired } }];

// Builds the downloadable .xlsx using exceljs — a self-hosted-n8n-only
// capability (Code nodes on n8n Cloud can't require npm packages).
// If you're on n8n Cloud instead, replace this node with an HTTP
// Request to a conversion service, or export straight from the Google
// Sheet created above (File > Download > .xlsx) as a manual fallback.
const ExcelJS = require('exceljs');

const { auditId, costing, summary, reviewRequired } = $('Calculate Profitability').first().json;

const wb = new ExcelJS.Workbook();

const costingSheet = wb.addWorksheet('Costing & Profit');
costingSheet.columns = [
  { header: 'Item', key: 'name', width: 28 },
  { header: 'Category', key: 'category', width: 16 },
  { header: 'Selling Price', key: 'sellingPrice', width: 14 },
  { header: 'Ingredient Cost', key: 'ingredientCost', width: 16 },
  { header: 'GP / Portion', key: 'grossProfitPerPortion', width: 14 },
  { header: 'GP %', key: 'gpPercent', width: 10 },
  { header: 'Units Sold', key: 'unitsSold', width: 12 },
  { header: 'Total GP Contribution', key: 'totalGpContribution', width: 18 },
  { header: 'Sales Mix %', key: 'salesMixPercent', width: 12 },
  { header: 'Confidence', key: 'confidence', width: 12 },
];
costing.forEach((row) => costingSheet.addRow(row));

const reviewSheet = wb.addWorksheet('Review Required');
reviewSheet.columns = [
  { header: 'Item', key: 'item', width: 28 },
  { header: 'Reason', key: 'reason', width: 40 },
  { header: 'Detail', key: 'detail', width: 40 },
];
reviewRequired.forEach((row) => reviewSheet.addRow(row));

const summarySheet = wb.addWorksheet('Audit Summary');
summarySheet.columns = [
  { header: 'Field', key: 'field', width: 24 },
  { header: 'Value', key: 'value', width: 40 },
];
Object.entries(summary).forEach(([field, value]) => summarySheet.addRow({ field, value }));

const buffer = await wb.xlsx.writeBuffer();

return [{
  json: { auditId, fileName: `Menu-Profit-Report-${auditId}.xlsx` },
  binary: {
    report: {
      data: Buffer.from(buffer).toString('base64'),
      mimeType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      fileName: `Menu-Profit-Report-${auditId}.xlsx`,
    },
  },
}];

// Shared landing spot for every node's error output (wired below).
// Figures out which audit this was for, so the failure can still be
// reported back even though the main happy-path never reached the end.
const error = $json.error ?? String($json);
const auditId = $('Webhook').first()?.json?.body?.auditId ?? $('Parse Spreadsheet Files').first()?.json?.auditId ?? null;

return [{ json: { auditId, message: typeof error === 'string' ? error : JSON.stringify(error) } }];
